mapper.select:
SELECT p.id, p.user_id, p.body, p.created_at, p.updated_at, u.username AS author_username, u.display_name AS author_display_name, u.avatar_key AS author_avatar_key FROM posts p JOIN users u ON u.id = p.user_id WHERE p.user_id = #{userId} AND p.deleted_at IS NULL
AND (p.created_at, p.id) < (#{cursorCreatedAt}, #{cursorId})
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit}
